SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "王骥", "aliases": ["王驥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德9年（年号对照1434年）三月，王骥出任兵部尚书。", "biography": null, "status": "draft", "id": "4a558c65-f1f5-51f5-90df-5aa57564c8bb"}, {"name": "钱氏（明英宗孝庄睿皇后）", "aliases": ["孝庄睿皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "钱氏（明英宗孝庄睿皇后）受册为皇后。", "biography": null, "status": "draft", "id": "ba16a921-8e35-58e6-86ee-efc3cf961160"}, {"name": "张氏（明仁宗诚孝昭皇后）", "aliases": ["诚孝昭皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "张氏是朱高炽的妃，朱高炽即位后册立她为皇后。", "biography": null, "status": "draft", "id": "d98838f2-35b9-58ff-8f19-a2588ec64e18"}, {"name": "思机发", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "思机发为明军征讨对象。", "biography": null, "status": "draft", "id": "4b70c1c9-54ce-526f-96a9-c56865625ed0"}, {"name": "刘球", "aliases": ["刘廷振"], "era": "明", "birth_year": null, "death_year": null, "description": "刘球上奏十事后被下狱，并在狱中被杀。", "biography": null, "status": "draft", "id": "30a58978-ca5a-5dc8-b218-93d17477484b"}, {"name": "王振（明英宗朝宦官）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "王振（明英宗朝宦官）掌管司礼监。", "biography": null, "status": "draft", "id": "b348fa2c-6cc7-57f7-9f9b-3198d1f7128a"}, {"name": "薛瑄", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，薛瑄升任礼部右侍郎，兼翰林学士并入阁。", "biography": null, "status": "draft", "id": "db674166-9da7-54f1-a2f6-4de92f9842f6"}, {"name": "李时勉", "aliases": ["李懋"], "era": "明", "birth_year": null, "death_year": null, "description": "李时勉以侍读身份被下狱。", "biography": null, "status": "draft", "id": "c925d68f-aef6-5e23-93cb-cd7a19e52416"}, {"name": "胡善祥", "aliases": ["恭让章皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "胡善祥被立为皇后。", "biography": null, "status": "draft", "id": "899c42d7-6f22-5ca0-a482-61161e914b39"}, {"name": "思任发", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "思任发为明军征讨对象。", "biography": null, "status": "draft", "id": "98ce9322-c7cd-5041-b4aa-37cc7d6ec513"}]'::jsonb)
